CREATE TABLE IF NOT EXISTS installations(id TEXT PRIMARY KEY,mode TEXT NOT NULL CHECK(mode IN('DEMO','LOCAL_RESEARCH')),schemaVersion INTEGER NOT NULL,appCodeSha TEXT NOT NULL,createdAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,csrf TEXT NOT NULL,expiresAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bootstrap_uses(hash TEXT PRIMARY KEY,at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fixtures(id TEXT PRIMARY KEY,home TEXT NOT NULL,away TEXT NOT NULL,currentRevision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'SCHEDULED',CHECK(home<>away));
CREATE TABLE IF NOT EXISTS source_snapshots(id TEXT PRIMARY KEY,providerId TEXT NOT NULL,resourceKey TEXT NOT NULL,observedAt INTEGER NOT NULL,ingestedAt INTEGER NOT NULL,providerUpdatedAt INTEGER,payloadHash TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('DEMO','LOCAL_RESEARCH')),contentState TEXT NOT NULL CHECK(contentState='COMPLETE'),UNIQUE(providerId,resourceKey,observedAt,payloadHash));
CREATE TABLE IF NOT EXISTS source_chunks(snapshotId TEXT NOT NULL REFERENCES source_snapshots(id),chunkNo INTEGER NOT NULL,content TEXT NOT NULL CHECK(length(content)<=262144),PRIMARY KEY(snapshotId,chunkNo));
CREATE TABLE IF NOT EXISTS fixture_revisions(id TEXT PRIMARY KEY,fixtureId TEXT NOT NULL REFERENCES fixtures(id),revision INTEGER NOT NULL,kickoffAt INTEGER NOT NULL,observedAt INTEGER NOT NULL,sourceSnapshotId TEXT NOT NULL REFERENCES source_snapshots(id),UNIQUE(fixtureId,revision));
CREATE TABLE IF NOT EXISTS market_definitions(id TEXT PRIMARY KEY,fixtureId TEXT NOT NULL REFERENCES fixtures(id),specHash TEXT NOT NULL UNIQUE,period TEXT NOT NULL CHECK(period='REGULATION_90'),type TEXT NOT NULL CHECK(type='1X2'));
CREATE TABLE IF NOT EXISTS quote_sets(id TEXT PRIMARY KEY,marketId TEXT NOT NULL REFERENCES market_definitions(id),sourceSnapshotId TEXT NOT NULL REFERENCES source_snapshots(id),providerId TEXT NOT NULL,observedAt INTEGER NOT NULL,providerUpdatedAt INTEGER,phase TEXT NOT NULL,suspended INTEGER NOT NULL CHECK(suspended IN(0,1)),setHash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quote_selections(id TEXT PRIMARY KEY,quoteSetId TEXT NOT NULL REFERENCES quote_sets(id),selection TEXT NOT NULL CHECK(selection IN('HOME','DRAW','AWAY')),decimalOdds TEXT NOT NULL CHECK(CAST(decimalOdds AS REAL)>1),rawValue TEXT NOT NULL,rawFormat TEXT NOT NULL CHECK(rawFormat='decimal'),UNIQUE(quoteSetId,selection));
CREATE TABLE IF NOT EXISTS observation_slots(id TEXT PRIMARY KEY,fixtureRevisionId TEXT NOT NULL REFERENCES fixture_revisions(id),protocolId TEXT NOT NULL,scheduledAt INTEGER NOT NULL,deadlineAt INTEGER NOT NULL,state TEXT NOT NULL,reason TEXT,UNIQUE(fixtureRevisionId,protocolId,scheduledAt));
CREATE TABLE IF NOT EXISTS input_bundles(id TEXT PRIMARY KEY,slotId TEXT NOT NULL UNIQUE REFERENCES observation_slots(id),quoteSetId TEXT NOT NULL REFERENCES quote_sets(id),cutoffAt INTEGER NOT NULL,manifestHash TEXT NOT NULL,canonical TEXT NOT NULL,state TEXT NOT NULL CHECK(state='READY'));
CREATE TABLE IF NOT EXISTS model_manifests(id TEXT PRIMARY KEY,manifestJson TEXT NOT NULL,manifestHash TEXT NOT NULL,outputKind TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feature_snapshots(id TEXT PRIMARY KEY,bundleId TEXT NOT NULL REFERENCES input_bundles(id),modelId TEXT NOT NULL REFERENCES model_manifests(id),featureHash TEXT NOT NULL,canonical TEXT NOT NULL,UNIQUE(bundleId,modelId));
CREATE TABLE IF NOT EXISTS predictions(id TEXT PRIMARY KEY,slotId TEXT NOT NULL REFERENCES observation_slots(id),fixtureRevisionId TEXT NOT NULL REFERENCES fixture_revisions(id),modelId TEXT NOT NULL REFERENCES model_manifests(id),featureSnapshotId TEXT NOT NULL REFERENCES feature_snapshots(id),calculatedAt INTEGER NOT NULL,centralJson TEXT NOT NULL,predictionHash TEXT NOT NULL,UNIQUE(slotId,modelId));
CREATE TABLE IF NOT EXISTS market_expectations(id TEXT PRIMARY KEY,predictionId TEXT NOT NULL REFERENCES predictions(id),quoteSelectionId TEXT NOT NULL REFERENCES quote_selections(id),expectedReturn REAL NOT NULL,ev REAL NOT NULL,probability REAL NOT NULL CHECK(probability>=0 AND probability<=1),pricingVersion TEXT NOT NULL,UNIQUE(predictionId,quoteSelectionId,pricingVersion));
CREATE TABLE IF NOT EXISTS decisions(id TEXT PRIMARY KEY,expectationId TEXT NOT NULL UNIQUE REFERENCES market_expectations(id),accepted INTEGER NOT NULL CHECK(accepted IN(0,1)),reason TEXT NOT NULL,decidedAt INTEGER NOT NULL,strategyVersion TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portfolios(id TEXT PRIMARY KEY,mode TEXT NOT NULL CHECK(mode='DEMO'),revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0),available INTEGER NOT NULL CHECK(abs(available)<=9007199254740991),openStake INTEGER NOT NULL CHECK(openStake>=0 AND openStake<=9007199254740991),realized INTEGER NOT NULL CHECK(abs(realized)<=9007199254740991),initial INTEGER NOT NULL CHECK(initial>=0),frozen INTEGER NOT NULL DEFAULT 0,CHECK(available+openStake=initial+realized));
CREATE TABLE IF NOT EXISTS command_receipts(id TEXT PRIMARY KEY,scope TEXT NOT NULL,idempotencyKey TEXT NOT NULL,requestHash TEXT NOT NULL,guard INTEGER NOT NULL CHECK(guard=1),resultRef TEXT NOT NULL,committedAt INTEGER NOT NULL,UNIQUE(scope,idempotencyKey));
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY,portfolioId TEXT NOT NULL REFERENCES portfolios(id),decisionId TEXT NOT NULL REFERENCES decisions(id),stakeAtoms INTEGER NOT NULL CHECK(stakeAtoms>0 AND stakeAtoms<=9007199254740991),createdAt INTEGER NOT NULL,businessKey TEXT NOT NULL,placementDay TEXT NOT NULL,origin TEXT NOT NULL CHECK(origin='DEMO'),UNIQUE(portfolioId,businessKey));
CREATE TABLE IF NOT EXISTS ticket_legs(id TEXT PRIMARY KEY,ticketId TEXT NOT NULL UNIQUE REFERENCES tickets(id),fixtureRevisionId TEXT NOT NULL REFERENCES fixture_revisions(id),quoteSelectionId TEXT NOT NULL REFERENCES quote_selections(id),predictionId TEXT NOT NULL REFERENCES predictions(id),frozenOdds TEXT NOT NULL,selection TEXT NOT NULL,marketSpecJson TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_state(ticketId TEXT PRIMARY KEY REFERENCES tickets(id),revision INTEGER NOT NULL,currentStatus TEXT NOT NULL CHECK(currentStatus IN('OPEN','REVIEW','SETTLED','REOPENED')),gross INTEGER NOT NULL DEFAULT 0,currentSettlementId TEXT);
CREATE TABLE IF NOT EXISTS result_observations(id TEXT PRIMARY KEY,fixtureId TEXT NOT NULL REFERENCES fixtures(id),sourceSnapshotId TEXT NOT NULL REFERENCES source_snapshots(id),regulationJson TEXT,status TEXT NOT NULL,observedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS result_adjudications(id TEXT PRIMARY KEY,fixtureId TEXT NOT NULL REFERENCES fixtures(id),revision INTEGER NOT NULL,state TEXT NOT NULL,regulationJson TEXT,evidenceRefs TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,supersedesId TEXT REFERENCES result_adjudications(id),UNIQUE(fixtureId,revision));
CREATE TABLE IF NOT EXISTS settlement_events(id TEXT PRIMARY KEY,ticketId TEXT NOT NULL REFERENCES tickets(id),revision INTEGER NOT NULL,kind TEXT NOT NULL,adjudicationId TEXT NOT NULL REFERENCES result_adjudications(id),previousSettlementId TEXT REFERENCES settlement_events(id),gross INTEGER NOT NULL,delta INTEGER NOT NULL,at INTEGER NOT NULL,mathVersion TEXT NOT NULL,UNIQUE(ticketId,revision),UNIQUE(ticketId,adjudicationId));
CREATE TABLE IF NOT EXISTS ledger_entries(id TEXT PRIMARY KEY,portfolioId TEXT NOT NULL REFERENCES portfolios(id),commandId TEXT NOT NULL REFERENCES command_receipts(id),ticketId TEXT REFERENCES tickets(id),settlementEventId TEXT REFERENCES settlement_events(id),type TEXT NOT NULL,availableDelta INTEGER NOT NULL,openDelta INTEGER NOT NULL,realizedDelta INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,bundleId TEXT NOT NULL REFERENCES input_bundles(id),modelId TEXT NOT NULL REFERENCES model_manifests(id),state TEXT NOT NULL,fencingToken INTEGER NOT NULL DEFAULT 0,leaseOwner TEXT,leaseUntil INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,deadlineAt INTEGER NOT NULL,reason TEXT,UNIQUE(bundleId,modelId));
CREATE TABLE IF NOT EXISTS fault_guard(value INTEGER NOT NULL CHECK(value=1));
CREATE INDEX IF NOT EXISTS ticket_page ON tickets(createdAt,id);
CREATE INDEX IF NOT EXISTS fixture_page ON fixture_revisions(kickoffAt,id);
CREATE INDEX IF NOT EXISTS job_queue ON jobs(state,leaseUntil,deadlineAt);
CREATE INDEX IF NOT EXISTS quote_page ON quote_sets(marketId,observedAt,id);
CREATE INDEX IF NOT EXISTS settlement_ticket ON settlement_events(ticketId,revision);
